/* Base geometry for EVERY workspace button, active or not. Both states get the
   identical box — same padding, margin, min-size, and a 1px border (transparent
   while inactive) — so activating a workspace only swaps colour and paints the
   pokeball; the button never changes size. Previously only .active carried this
   geometry, so the active button was taller/wider than the plain numbers and
   the bar jumped vertically as the active state moved between workspaces.
   :not(.taskbar) keeps this off the taskbar module's buttons. */
#workspaces:not(.taskbar) button {
    padding: 4px 4px;
    margin: 4px 0px;
    min-width: 20px;
    min-height: 20px;
    border: 1px solid transparent; /* reserve the 1px the active state makes visible */
    border-radius: 10px;
    background-color: transparent;
    color: @outline; /* the workspace number */
}

#workspaces:not(.taskbar) button.active {
    background-image: url('/home/krubics/.config/waybar/assets/pokeball.png');
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
    background-origin: content-box; /* inset the ball from the accent pill's edges */
    background-color: @primary;
    color: transparent; /* hides the workspace number behind the pokeball */
    border-color: @outline; /* same 1px width as inactive — now visible */
}

